"""Source-grounded facts generated by the trainable QFAD writer."""
import json

WRITER_PROMPT = '''Write a medical memory graph from the supplied source records. Return JSON only:
{"sources":[{"source_id":"...","facts":[{"subject":"...","relation":"...","object":"...","polarity":"affirmed|negated","certainty":"...","status":"...","time":"...","evidence_ids":[1,2]}]}]}.
Every fact must include all eight keys shown in the schema. The relation is a predicate connecting subject to object: put the target or result in object, rather than writing a whole sentence in relation. For each source, replace its old facts with supported facts worth remembering. Preserve who experienced or said each fact, doses, measurements, uncertainty, negation, medication start/stop events and changes over time. A clinician's suggestion is not a completed patient action. A suspected diagnosis is not confirmed. Distinguish the patient from relatives and other people using the record header. Polarity says whether the subject-relation-object statement is affirmed or denied; an affirmative warning against an action is not a negated warning. Certainty must contain the actual epistemic status of each fact: reported, observed, suspected, confirmed, recommended, planned, or general_information. Choose it separately for each fact. Use confirmed only for an explicitly confirmed diagnosis or finding; an explanation or suggestion alone does not establish confirmation. Attribute a clinician's explanation to the clinician rather than treating it as the patient's own belief. Use the record date for relative events only when justified by the source; otherwise retain the original relative wording. Use an empty string for an unstated status or time. Cite the integer IDs of the source spans supporting each fact. Include every supplied source_id once. Do not infer new clinical conclusions. There is no question to answer: write reusable facts and relations from these records.'''


def source_spans(source):
    return [{'id': i, 'text': line} for i,line in enumerate(source['text'].splitlines()) if line.strip()]


def messages(sources):
    return [{'role': 'system', 'content': WRITER_PROMPT},
            {'role': 'user', 'content': json.dumps({'sources': [
                {'source_id':s['source_id'],'spans':source_spans(s),'old_facts':s['old_facts']} for s in sources]}, ensure_ascii=False)}]


def parse_output(text, sources):
    data = json.loads(text)
    original = {s['source_id']: s for s in sources}
    rows = data['sources']
    if len(rows) != len(original) or {r['source_id'] for r in rows} != set(original):
        raise ValueError('Writer source coverage differs from input')
    fields = {'subject', 'relation', 'object', 'polarity', 'certainty', 'status', 'time'}
    for row in rows:
        for fact in row['facts']:
            if set(fact) != fields|{'evidence_ids'} or not all(isinstance(fact[k], str) for k in fields):
                raise ValueError('Fact fields must match the graph schema')
            if not all(fact[k].strip() for k in ('subject', 'relation', 'object')):
                raise ValueError('Fact or evidence is empty')
            spans={s['id']:s['text'] for s in source_spans(original[row['source_id']])}
            ids=fact['evidence_ids']
            if not isinstance(ids,list) or not ids or any(type(i) is not int or i not in spans for i in ids):
                raise ValueError('Evidence IDs must refer to supplied source spans')
            fact['evidence']='\n'.join(spans[i] for i in ids)
            if fact['polarity'] not in ('affirmed', 'negated'):
                raise ValueError('Invalid polarity')
    return rows


def fact_text(fact):
    qualifiers = '; '.join(f'{k}={fact[k]}' for k in ('polarity', 'certainty', 'status', 'time') if fact.get(k))
    return f'{fact["subject"]} | {fact["relation"]} | {fact["object"]}' + (f' [{qualifiers}]' if qualifiers else '')
